"""Synthesized instruments - everything here is generated by this code, so the output belongs
to the user outright (catalog license "Synthesized").

Engines (one note in, stereo float32 out):
  subtractive  band-limited saw/square/pulse/triangle/sine + noise, unison, resonant filter
               with envelope + LFO, amp ADSR, glide-free           -> leads, basses, pads, chip
  fm           2-operator pairs (carrier/modulator) with decaying indices -> e-piano, bells, FM bass
  organ        9 drawbars of additive sines, key click, percussion  -> tonewheel organs
  pluck        Karplus-Strong at an oversampled rate, pluck position, body EQ, jawari buzz,
               double courses, tremolo picking                       -> sitar, koto, oud, mandolin...
  voice        ensembles of glottal sources through vowel formant banks -> choir / solo vowels
  additive     decaying partials (struck bars, tines)              -> celesta, music box, bells
  wind         tone + breath + chiff with formant shaping and vibrato -> pan flute, shakuhachi, duduk
Drum machines (808/909-style) are synthesized hit by hit and cached as WAV files so they work
as kits (catalog.kit).
"""
import hashlib
from pathlib import Path

import numpy as np
from scipy.signal import lfilter, resample_poly

from .fx import biquad, eq as fx_eq

SR = 48000


# ------------------------------------------------------------------ building blocks

def adsr(n, a, d, s, r, dur_n):
    """ADSR over n samples; note-off at dur_n samples; release r seconds after that."""
    env = np.empty(n, np.float32)
    an, dn = max(1, int(a * SR)), max(1, int(d * SR))
    t = np.arange(n)
    env[:] = s
    m = t < an
    env[m] = t[m] / an
    m = (t >= an) & (t < an + dn)
    env[m] = 1 - (1 - s) * (t[m] - an) / dn
    off = min(dur_n, n)
    level = env[off - 1] if off > 0 else 0.0
    rn = max(1, int(r * SR))
    tail = t >= off
    env[tail] = level * np.exp(-6.9 * (t[tail] - off) / rn)
    return env


def _polyblep(t, dt):
    r = np.zeros_like(t)
    m = t < dt
    x = t[m] / dt[m]
    r[m] = x + x - x * x - 1
    m = t > 1 - dt
    x = (t[m] - 1) / dt[m]
    r[m] = x * x + x + x + 1
    return r


def osc(freq, wave="saw", pw=0.5, phase0=0.0):
    """freq: per-sample frequency array. Band-limited (PolyBLEP) classic waveforms."""
    dt = np.clip(freq / SR, 1e-7, 0.49)
    ph = (phase0 + np.cumsum(dt)) % 1.0
    if wave == "sine":
        return np.sin(2 * np.pi * ph)
    if wave == "saw":
        return 2 * ph - 1 - _polyblep(ph, dt)
    if wave in ("square", "pulse"):
        w = 0.5 if wave == "square" else pw
        sq = np.where(ph < w, 1.0, -1.0)
        return sq + _polyblep(ph, dt) - _polyblep((ph - w) % 1.0, dt)
    if wave == "triangle":
        sq = np.where(ph < 0.5, 1.0, -1.0) + _polyblep(ph, dt) - _polyblep((ph - 0.5) % 1.0, dt)
        tri = lfilter([4 * float(np.mean(dt))], [1, -0.9995], sq)
        return tri / (np.abs(tri).max() + 1e-9)
    raise ValueError(wave)


def tv_filter(x, cutoff, kind="lp", q=0.8, poles=2, block=128):
    """Filter with a per-sample cutoff curve (coefficients updated per block)."""
    x = np.asarray(x, np.float64)
    if np.ptp(cutoff) < 1e-3:
        for _ in range(poles // 2):
            b, a = biquad(kind, float(cutoff[0]), q)
            x = lfilter(b, a, x)
        return x
    y = np.empty_like(x)
    zis = [np.zeros(2) for _ in range(poles // 2)]
    for i in range(0, len(x), block):
        s = slice(i, min(len(x), i + block))
        seg = x[s]
        b, a = biquad(kind, float(np.clip(cutoff[i], 20, SR * 0.45)), q)
        for k in range(len(zis)):
            seg, zis[k] = lfilter(b, a, seg, zi=zis[k])
        y[s] = seg
    return y


def hz(midi):
    return 440.0 * 2 ** ((midi - 69) / 12)


def _stereo(mono, spread_ms=0.0):
    if spread_ms:
        d = int(spread_ms * SR / 1000)
        right = np.concatenate([np.zeros(d), mono[:-d]]) if d else mono
        return np.stack([mono, right], axis=1).astype(np.float32)
    return np.stack([mono, mono], axis=1).astype(np.float32)


# ------------------------------------------------------------------ engines

def subtractive(f0, dur, vel, p, rng):
    rel = p.get("release", 0.3)
    n = int((dur + rel + 0.02) * SR)
    t = np.arange(n) / SR
    lfo_rate, lfo_pitch = p.get("lfo_rate", 5.0), p.get("lfo_pitch", 0.0)
    vib = lfo_pitch / 1200 * np.sin(2 * np.pi * lfo_rate * t) * np.clip(t / max(1e-3, p.get("vib_delay", 0.0) + 1e-3), 0, 1)
    glide = p.get("pitch_env", 0.0) * np.exp(-t / max(1e-3, p.get("pitch_env_time", 0.05)))    # semitones
    out = np.zeros((n, 2))
    voices = p.get("unison", 1)
    spread = p.get("spread", 0.0)
    for v in range(voices):
        det = (v - (voices - 1) / 2) / max(1, voices - 1) * spread if voices > 1 else 0.0
        pan = (v / max(1, voices - 1)) * 2 - 1 if voices > 1 else 0.0
        sig = np.zeros(n)
        for wave, level, semis in p.get("osc", [("saw", 1.0, 0)]):
            fr = f0 * 2 ** ((semis + det / 100 + glide) / 12 + vib)
            sig += level * osc(fr, wave, p.get("pw", 0.5), rng.uniform(0, 1))
        out[:, 0] += sig * np.sqrt((1 - pan * 0.9) / 2)
        out[:, 1] += sig * np.sqrt((1 + pan * 0.9) / 2)
    if p.get("noise"):
        out += p["noise"] * np.random.default_rng(rng.randint(0, 1 << 30)).standard_normal((n, 2)) * 0.3
    if p.get("cutoff"):
        fa, fd, fs, fr = p.get("fenv", (0.005, 0.3, 0.0, 0.3))
        fenv = adsr(n, fa, fd, fs, fr, int(dur * SR))
        lfo_f = p.get("lfo_cutoff", 0.0) * np.sin(2 * np.pi * p.get("lfo_cutoff_rate", lfo_rate) * t)
        cut = p["cutoff"] * 2 ** (p.get("keytrack", 0.5) * np.log2(f0 / 261.6) + p.get("fenv_amt", 0.0) * fenv * (0.5 + 0.5 * vel) + lfo_f)
        for c in range(2):
            out[:, c] = tv_filter(out[:, c], cut, p.get("ftype", "lp"), p.get("res", 0.8), p.get("poles", 2))
    if p.get("drive"):
        out = np.tanh(out * p["drive"]) / np.tanh(p["drive"])
    a, d, s, r = p.get("env", (0.005, 0.2, 0.8, rel))
    out *= adsr(n, a, d, s, r, int(dur * SR))[:, None]
    return out


def fm(f0, dur, vel, p, rng):
    rel = p.get("release", 0.4)
    n = int((dur + rel + 0.02) * SR)
    t = np.arange(n) / SR
    sig = np.zeros(n)
    # pairs: (carrier_ratio, carrier_level, mod_ratio, index, index_decay_s, carrier_decay_s)
    for cr, cl, mr, idx, idec, cdec in p["pairs"]:
        index = idx * (0.4 + 0.6 * vel) * np.exp(-t / max(1e-3, idec)) + p.get("index_floor", 0.0)
        mod = index * np.sin(2 * np.pi * f0 * mr * t + rng.uniform(0, 6))
        car = np.sin(2 * np.pi * f0 * cr * t + mod)
        decay = cdec * (261.6 / f0) ** p.get("decay_keyscale", 0.4)
        sig += cl * car * np.exp(-t / max(1e-3, decay))
    a, d, s, r = p.get("env", (0.002, 0.1, 1.0, rel))
    sig *= adsr(n, a, d, s, r, int(dur * SR))
    if p.get("tremolo"):
        sig *= 1 - p["tremolo"] * (0.5 + 0.5 * np.sin(2 * np.pi * p.get("tremolo_rate", 5.5) * t))
    return _stereo(sig, p.get("spread_ms", 0.4))


DRAWBAR_RATIOS = [0.5, 1.5, 1, 2, 3, 4, 5, 6, 8]


def organ(f0, dur, vel, p, rng):
    rel = p.get("release", 0.06)
    n = int((dur + rel + 0.01) * SR)
    t = np.arange(n) / SR
    sig = np.zeros(n)
    for level, ratio in zip(p["drawbars"], DRAWBAR_RATIOS):
        if level <= 0:
            continue
        f = f0 * ratio
        if f > 7000:            # tonewheel foldback: highest wheels drop out
            continue
        amp = 10 ** ((level - 8) * 3 / 20)
        sig += amp * np.sin(2 * np.pi * f * t + rng.uniform(0, 6))
    if p.get("percussion"):
        harm = 2 if p["percussion"] == "2nd" else 3
        sig += 0.7 * np.sin(2 * np.pi * f0 * harm * t) * np.exp(-t / p.get("perc_decay", 0.25))
    if p.get("click", 0.0):
        k = int(0.004 * SR)
        click = np.zeros(n)
        click[:k] = np.random.default_rng(rng.randint(0, 1 << 30)).standard_normal(k) * np.hanning(2 * k)[:k][::-1]
        b, a = biquad("bp", 2500, 0.7)
        sig += p["click"] * lfilter(b, a, click)
    env = adsr(n, 0.005, 0.01, 1.0, rel, int(dur * SR))
    return _stereo(sig * env, 0.3)


def pluck(f0, dur, vel, p, rng):
    """Karplus-Strong in period-sized chunks at an oversampled rate (accurate tuning)."""
    rel = p.get("release", 0.25)
    total = dur + rel
    if p.get("tremolo"):                     # mandolin/balalaika tremolo picking
        step = 1 / p["tremolo"]
        out = None
        k = 0
        while k * step < dur:
            v = vel * (0.85 + 0.15 * rng.random()) * (1.0 if k % 2 == 0 else 0.85)
            q = dict(p, tremolo=0)
            note = pluck(f0, min(step * 1.6, dur - k * step + 0.05), v, q, rng)
            i = int(k * step * SR)
            if out is None:
                out = np.zeros((int(total * SR) + len(note), 2))
            out[i:i + len(note)] += note
            k += 1
        return out[: int(total * SR)]
    os_ = int(np.clip(np.ceil(220 * f0 / SR), 1, 16))
    fs = SR * os_
    period = fs / f0
    t60 = p.get("decay", 3.0) * (220 / f0) ** p.get("decay_keyscale", 0.5)
    g = 10 ** (-3 / (t60 * f0))
    S = p.get("damping", 0.5)               # 0.5 = classic average (darker); smaller = brighter
    total_n = int(total * fs)
    nr = np.random.default_rng(rng.randint(0, 1 << 30))
    courses = p.get("courses", 1)
    mix = np.zeros(total_n)
    for c in range(courses):
        cents = (c - (courses - 1) / 2) * p.get("course_detune", 3.0)
        per = period * 2 ** (-cents / 1200)
        Nc = max(2, int(round(per - 0.5)))
        exc = nr.uniform(-1, 1, Nc)
        bright = p.get("brightness", 0.6) * (0.5 + 0.5 * vel)
        a1 = np.clip(1 - bright, 0.0, 0.98)
        exc = lfilter([1 - a1], [1, -a1], exc)
        pos = p.get("pluck_pos", 0.13)
        sh = max(1, int(pos * Nc))
        exc = exc - np.roll(exc, sh)
        exc -= exc.mean()
        y = np.zeros(total_n + Nc + 1)
        y[1:Nc + 1] = exc
        buzz = p.get("buzz", 0.0)
        k = 1
        while (k + 1) * Nc + 1 <= len(y):
            prev = y[(k - 1) * Nc + 1: k * Nc + 1]
            prev2 = y[(k - 1) * Nc: k * Nc]
            chunk = g * ((1 - S) * prev + S * prev2)
            if buzz:
                pk = np.abs(chunk).max() + 1e-12
                thr = pk * (1 - buzz * 0.6)
                chunk = np.where(chunk > thr, thr + (chunk - thr) * 0.25, chunk)
            y[k * Nc + 1:(k + 1) * Nc + 1] = chunk
            k += 1
        mix += y[1:total_n + 1] / courses
    if os_ > 1:
        mix = resample_poly(mix, 1, os_)
    n = len(mix)
    if p.get("thump"):                       # skin/body knock (shamisen, banjo)
        tt = np.arange(n) / SR
        mix += p["thump"] * np.sin(2 * np.pi * p.get("thump_hz", 160) * tt) * np.exp(-tt / 0.03) * np.abs(mix[:200]).max()
    env = adsr(n, 0.0005, 0.01, 1.0, rel, int(dur * SR))
    mix = mix * env
    st = _stereo(mix, p.get("spread_ms", 0.25))
    if p.get("body"):
        st = fx_eq(st, p["body"])
    for d in p.get("sympathetic", []):       # sitar-like sympathetic strings ringing
        tt = np.arange(n) / SR
        ring = 0.04 * np.sin(2 * np.pi * f0 * 2 ** (d / 12) * tt) * (1 - np.exp(-tt / 0.05)) * np.exp(-tt / 2.5)
        st += ring[:, None] * np.abs(mix).max()
    return st


