class SynthInstrument:
    """Same render() interface as sampled instruments."""

    def __init__(self, name, patch):
        self.name = name
        self.patch = dict(PATCHES[patch]) if isinstance(patch, str) else dict(patch)
        lo, hi = self.patch.get("range", (24, 108))
        self.roots = np.arange(lo, hi + 1)
        self.sustain = True
        self.release = self.patch.get("release", 0.3)

    def render(self, midi, dur, vel=0.7, rng=None, attack=None, release=None, cents=0.0):
        import random
        rng = rng or random.Random(0)
        p = dict(self.patch)
        if release is not None:
            p["release"] = release
            if "env" in p:
                a, d, s, _ = p["env"]
                p["env"] = (a, d, s, release)
        if attack is not None and "env" in p:
            a, d, s, r = p["env"]
            p["env"] = (attack, d, s, r)
        f0 = hz(midi + cents / 100)
        y = ENGINES[p["engine"]](f0, dur, vel, p, rng)
        y = np.asarray(y, np.float32)
        y /= (np.abs(y).max() + 1e-9)
        return (y * (0.25 + 0.75 * vel ** 1.6) * 0.5).astype(np.float32)


# ------------------------------------------------------------------ drum machines

def _noise(n, seed):
    return np.random.default_rng(seed).standard_normal(n)


def _metal(n, freqs, seed=0):
    t = np.arange(n) / SR
    s = np.zeros(n)
    for f in freqs:
        s += np.sign(np.sin(2 * np.pi * f * t + seed))
    return s


METAL_808 = [205.3, 304.4, 369.6, 522.7, 540.0, 800.0]


def drum(kit, name, seed=1):
    """One drum-machine hit -> mono float array. kit: '808' or '909'."""
    def env(n, tau, attack=0.0005):
        t = np.arange(n) / SR
        return np.exp(-t / tau) * np.clip(t / attack, 0, 1)
    if name.startswith("kick"):
        long = name.endswith("long")
        dec = (1.2 if long else 0.55) if kit == "808" else 0.35
        n = int(dec * 4 * SR)
        t = np.arange(n) / SR
        f_end, f_start, sweep = (48, 140, 0.03) if kit == "808" else (52, 320, 0.012)
        f = f_end + (f_start - f_end) * np.exp(-t / sweep)
        s = np.sin(2 * np.pi * np.cumsum(f) / SR) * env(n, dec)
        if kit == "909":
            s += 0.5 * lfilter(*biquad("bp", 3500, 0.8), _noise(n, seed)) * env(n, 0.004)
            s = np.tanh(1.8 * s)
        else:
            s = np.tanh(1.2 * s)
        return s
    if name == "snare":
        n = int(0.5 * SR)
        t = np.arange(n) / SR
        tones = (180, 330) if kit == "808" else (190, 340)
        body = sum(np.sin(2 * np.pi * f * t) for f in tones) * env(n, 0.08 if kit == "808" else 0.06)
        nz = lfilter(*biquad("hp", 1800 if kit == "808" else 1200, 0.7), _noise(n, seed)) * env(n, 0.12 if kit == "808" else 0.18)
        return 0.6 * body + (0.8 if kit == "808" else 1.2) * nz
    if name == "clap":
        n = int(0.6 * SR)
        t = np.arange(n) / SR
        nz = lfilter(*biquad("bp", 1200, 1.2), _noise(n, seed))
        e = np.zeros(n)
        for k, off in enumerate((0.0, 0.011, 0.022, 0.031)):
            i = int(off * SR)
            e[i:] = np.maximum(e[i:], np.exp(-(t[: n - i]) / (0.008 if k < 3 else 0.15)))
        return nz * e
    if name in ("hat-closed", "hat-open", "cymbal", "ride"):
        dec = {"hat-closed": 0.045, "hat-open": 0.38, "cymbal": 1.4, "ride": 1.8}[name]
        n = int(dec * 5 * SR)
        m = _metal(n, METAL_808 if kit == "808" else [f * 1.2 for f in METAL_808], seed)
        if kit == "909" or name in ("cymbal", "ride"):
            m = m + (0.8 if kit == "909" else 0.4) * _noise(n, seed)
        lo = {"hat-closed": 7000, "hat-open": 7000, "cymbal": 4000, "ride": 3000}[name]
        s = lfilter(*biquad("hp", lo, 0.8), m)
        s = lfilter(*biquad("bp", lo * 1.4, 0.6), s) + 0.3 * s
        return s * env(n, dec)
    if name.startswith("tom"):
        f = {"tom-low": 80, "tom-mid": 120, "tom-high": 170}[name] * (1.0 if kit == "808" else 1.15)
        n = int(1.0 * SR)
        t = np.arange(n) / SR
        fr = f * (1 + 0.3 * np.exp(-t / 0.05))
        s = np.sin(2 * np.pi * np.cumsum(fr) / SR) * env(n, 0.25)
        return s + 0.05 * lfilter(*biquad("bp", 1000, 1.0), _noise(n, seed)) * env(n, 0.02)
    if name == "rim":
        n = int(0.1 * SR)
        return lfilter(*biquad("bp", 1700, 3.0), _noise(n, seed)) * env(n, 0.008) + \
            np.sin(2 * np.pi * 480 * np.arange(n) / SR) * env(n, 0.012)
    if name == "cowbell":
        n = int(0.6 * SR)
        t = np.arange(n) / SR
        s = np.sign(np.sin(2 * np.pi * 540 * t)) + np.sign(np.sin(2 * np.pi * 800 * t))
        s = lfilter(*biquad("bp", 900, 1.5), s)
        return s * (0.7 * env(n, 0.02) + 0.3 * env(n, 0.25))
    if name == "clave":
        n = int(0.15 * SR)
        return np.sin(2 * np.pi * 2500 * np.arange(n) / SR) * env(n, 0.02)
    if name == "maracas":
        n = int(0.12 * SR)
        return lfilter(*biquad("hp", 5000, 0.7), _noise(n, seed)) * env(n, 0.02, attack=0.004)
    raise ValueError(name)


DRUM_NAMES = ["kick", "kick-long", "snare", "clap", "hat-closed", "hat-open", "cymbal", "ride",
              "tom-low", "tom-mid", "tom-high", "rim", "cowbell", "clave", "maracas"]


def drum_kit_files(kit, folder):
    """Synthesize every hit of a kit to WAV files once (3 round-robin variants each)."""
    import soundfile as sf
    folder = Path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    stamp = folder / ".version"
    version = hashlib.sha1(Path(__file__).read_bytes()).hexdigest()[:12]
    if stamp.exists() and stamp.read_text() == version:
        return sorted(str(p) for p in folder.glob("*.wav"))
    for p in folder.glob("*.wav"):
        p.unlink()
    for name in DRUM_NAMES:
        for rr in range(3):
            s = drum(kit, name, seed=rr + 1)
            s = s / (np.abs(s).max() + 1e-9) * 0.9
            sf.write(folder / f"{kit}_{name}_rr{rr + 1}.wav", np.stack([s, s], 1).astype(np.float32), SR, subtype="PCM_24")
    stamp.write_text(version)
    return sorted(str(p) for p in folder.glob("*.wav"))
